sheets=json.loads((R/'eda/sheet_manifest.json').read_text());evaluations=json.loads((R.parents[1]/'shared/round3/evaluation_manifest.json').read_text())['records'];reviews=[]
for sheet in sheets:
    name=Path(sheet['path']).name;assert name in notes
    reviews.append({**sheet,'directly_inspected':True,'sha256':hashlib.sha256(Path(sheet['path']).read_bytes()).hexdigest(),'observations':notes[name],
      'rubric':{'recognizable_identity':'mixed; often uncertain after translation, especially Gaussian-style outputs','anatomy_markings':'visible losses or deformations in displayed variants','background_contamination':'donor-dependent backgrounds/palettes frequently transferred; latent backgrounds vary strongly','artifacts':'blur, halos, streaked textures or overbright/empty regions observed','plausible_variation':'not established; variation frequently destructive','self_control':'generally closer to original than translations, with smoothing/detail loss' if sheet['kind']!='milestone' else 'not shown on milestone sheet'}})
record=dict(review_method='Small unblinded AI direct visual review, not class accuracy or prevalence estimate',reviewed_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),sheets=reviews,representative_sources=64,representative_translations=512,representative_self_controls=64,tail_sources=8,milestone_sources=32,milestone_translations=320,all_reference_donors_displayed=True,uncertain_label_allowed=True,overall='Reference outputs often follow donor background and palette while damaging details; Gaussian styles offer larger pixel variation but frequently destroy recognizable identity. Self reconstruction is much closer. No readiness for augmentation established.')
(R/'visual_review.json').write_text(json.dumps(record,indent=2)+'\n')
